COPY public.table_metadata (id, schema_definition, short_description, table_name) FROM stdin;
1	CREATE TABLE routes (id BIGINT PRIMARY KEY, departure_location VARCHAR(255), arrival_location VARCHAR(255), base_price DECIMAL(38,2), distance_km DECIMAL(38,2), duration_minutes INT);	Chứa thông tin các tuyến đường xe chạy	routes
2	CREATE TABLE vehicles (id BIGINT PRIMARY KEY, license_plate VARCHAR(255), type VARCHAR(255), capacity INT);	Chứa thông tin xe và biển số	vehicles
3	CREATE TABLE trips (id BIGINT PRIMARY KEY, route_id BIGINT, vehicle_id BIGINT, departure_time TIMESTAMP, price DECIMAL(38,2), status VARCHAR(255));	Chứa thông tin các chuyến xe đang và sắp chạy	trips
4	CREATE TABLE customers (id UUID PRIMARY KEY, email VARCHAR(255), full_name VARCHAR(255), phone_number VARCHAR(255));	Chứa thông tin khách hàng, dùng để đối chiếu email người dùng đang đăng nhập	customers
5	CREATE TABLE bookings (id BIGINT PRIMARY KEY, customer_id UUID, trip_id BIGINT, status VARCHAR(255), total_price DECIMAL(38,2), created_at TIMESTAMP);	Chứa lịch sử đặt vé (hóa đơn) của khách hàng (customer_id)	bookings
6	CREATE TABLE tickets (id BIGINT PRIMARY KEY, booking_id BIGINT, seat_id BIGINT, price DECIMAL(38,2), status VARCHAR(255));	Chứa thông tin chi tiết từng vé (ghế ngồi) thuộc về một booking	tickets
\.
